json.dump(dict(collected='2026-10-14', logged_in='partly', photos=rows, excluded=[dict(files=f, reason=r) for f, r in EXCLUDED]),
          open('../media/media-manifest.json', 'w'), ensure_ascii=False, indent=2)
md = ['# מניפסט מדיה', '', 'נאסף בשני שלבים. ב-12.10.2026 בלי התחברות (19 קבצים). ב-13.10.2026 דרך הכרום המחובר של בעל החשבון: כל 446 הפריטים באלבום ״העלאות מהנייד״ נסקרו כתמונות ממוזערות (`media/facebook-thumbs`, האינדקס ב-`media/facebook-album-index.json`), ומתוכם הורדו 35 ברזולוציה מלאה. ב-14.10.2026 הורדו בלי התחברות עוד 38 קבצים מלאים (`tools/collect_fb_more.mjs`), ו-15 מהם נכנסו לאתר. הקבצים המקוריים שמורים ב-`media/facebook-originals`, והגרסאות המותאמות לאתר ב-`prototype/assets/photos` (רוחב עד 1920 ועד 820). ״מקום מאושר״ מסומן רק כשהמקום נראה בתמונה עצמה או כתוב בפוסט.', '',
      '| קובץ | מקור | מה רואים | מקום מאושר | כיוון | מידות | שימוש באתר |', '|---|---|---|---|---|---|---|']
for r in rows:
    md.append(f"| {r['filename']} | {r['source_url']} | {r['subject']} | {r['confirmed_location'] or 'לא מאושר'} | {r['orientation']} | {r['width']}×{r['height']} | {r['intended_use']} |")
md += ['', '## נאספו ולא נכנסו לאתר', ''] + [f'- `{f}`: {r}' for f, r in EXCLUDED]
open('../media/MEDIA_MANIFEST.md', 'w').write('\n'.join(md) + '\n')
print(len(rows), 'photos prepared')
